import React, { useState, useEffect } from 'react';
import axios from 'axios';
import './Categories.css'; // CSS fájl importálása

const Categories = () => {
    const [categories, setCategories] = useState([]);
    const [selectedCategory, setSelectedCategory] = useState(null);
    const [products, setProducts] = useState([]);

    // Kategóriák betöltése
    useEffect(() => {
        axios.get('http://localhost:5000/Card/category/Notebook')
            .then(response => {
                setCategories(['Notebook', 'Okostelefon', 'Fülhallgató', 'Okosóra', 'Tablet', 'VR Szemüveg']);
            })
            .catch(error => {
                console.error('Error fetching categories:', error);
            });
    }, []);

    // Termékek betöltése kategória alapján
    const fetchProductsByCategory = (category) => {
        axios.get(`http://localhost:5000/Card/category/${category}`)
            .then(response => {
                setProducts(response.data.products);
                setSelectedCategory(category);
            })
            .catch(error => {
                console.error('Error fetching products:', error);
            });
    };

    return (
        <div className="categories-container">
            <h1>Kategóriák</h1>
            <div className="category-buttons">
                {categories.map((category, index) => (
                    <button
                        key={index}
                        className={`category-button ${selectedCategory === category ? 'active' : ''}`}
                        onClick={() => fetchProductsByCategory(category)}
                    >
                        {category}
                    </button>
                ))}
            </div>

            <div className="products-list">
                {products.map(product => (
                    <div key={product.id} className="product-card">
                        <img src={product.image} alt={product.name} className="product-image" />
                        <h2>{product.name}</h2>
                        <p>{product.description}</p>
                        <p>Ár: {product.price} Ft</p>
                    </div>
                ))}
            </div>
        </div>
    );
};

export default Categories;
